{
  "name": "@amends-dev/harness",
  "version": "0.2.2",
  "description": "Runs an agent, such as opencode or one in your own process over an Effect AI language model, and streams every agent's turns in one format.",
  "license": "MIT",
  "homepage": "https://github.com/amends-dev/harness/tree/main/packages/harness#readme",
  "repository": {
    "type": "git",
    "url": "https://github.com/amends-dev/harness.git",
    "directory": "packages/harness"
  },
  "bugs": {
    "url": "https://github.com/amends-dev/harness/issues"
  },
  "keywords": [
    "agent",
    "ai",
    "effect",
    "harness",
    "mcp",
    "opencode",
    "sandbox"
  ],
  "type": "module",
  "sideEffects": false,
  "exports": {
    ".": "./index.js",
    "./*": "./*.js",
    "./internal/*": null
  },
  "dependencies": {
    "@amends-dev/sandbox": "^0.2.1"
  },
  "peerDependencies": {
    "effect": "~4.0.5"
  },
  "publishConfig": {
    "access": "public"
  }
}
